PRAGMA foreign_keys=ON;

CREATE TABLE IF NOT EXISTS couple_profile (id TEXT PRIMARY KEY,partner1_name TEXT NOT NULL DEFAULT '',partner1_avatar TEXT NOT NULL DEFAULT '',partner1_gender TEXT NOT NULL DEFAULT '',partner1_birthday TEXT,partner2_name TEXT NOT NULL DEFAULT '',partner2_avatar TEXT NOT NULL DEFAULT '',partner2_gender TEXT NOT NULL DEFAULT '',partner2_birthday TEXT,relationship_status TEXT NOT NULL DEFAULT 'dating',relationship_start TEXT NOT NULL DEFAULT (date('now')),created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS timeline_events (id TEXT PRIMARY KEY,couple_id TEXT,title TEXT NOT NULL,date TEXT NOT NULL,event_type TEXT NOT NULL DEFAULT 'custom',story TEXT DEFAULT '',photos TEXT NOT NULL DEFAULT '[]',location TEXT DEFAULT '',mood TEXT DEFAULT '',tags TEXT NOT NULL DEFAULT '[]',sort_order INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memories (id TEXT PRIMARY KEY,couple_id TEXT,title TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'photo',url TEXT NOT NULL DEFAULT '',description TEXT DEFAULT '',is_favorite INTEGER NOT NULL DEFAULT 0,date TEXT DEFAULT (date('now')),tags TEXT NOT NULL DEFAULT '[]',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS love_letters (id TEXT PRIMARY KEY,couple_id TEXT,title TEXT NOT NULL DEFAULT '',content TEXT NOT NULL DEFAULT '',from_partner TEXT NOT NULL DEFAULT 'partner1',to_partner TEXT NOT NULL DEFAULT 'partner2',is_draft INTEGER NOT NULL DEFAULT 1,is_locked INTEGER NOT NULL DEFAULT 0,scheduled_at TEXT,is_future INTEGER NOT NULL DEFAULT 0,reaction TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,delivered_at TEXT);
CREATE TABLE IF NOT EXISTS journal_entries (id TEXT PRIMARY KEY,couple_id TEXT,date TEXT NOT NULL DEFAULT (date('now')),content TEXT NOT NULL DEFAULT '',mood TEXT DEFAULT '',photos TEXT NOT NULL DEFAULT '[]',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS mood_entries (id TEXT PRIMARY KEY,couple_id TEXT,mood TEXT NOT NULL,note TEXT DEFAULT '',partner TEXT DEFAULT 'partner1',date TEXT,partner_id TEXT,partner_name TEXT,intensity REAL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS bucket_list_items (id TEXT PRIMARY KEY,couple_id TEXT,title TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'travel',description TEXT DEFAULT '',is_completed INTEGER NOT NULL DEFAULT 0,completed_at TEXT,image_url TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS anniversaries (id TEXT PRIMARY KEY,couple_id TEXT,title TEXT NOT NULL,date TEXT NOT NULL,anniversary_type TEXT NOT NULL DEFAULT 'custom',recurrence TEXT DEFAULT 'yearly',photo_url TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS map_locations (id TEXT PRIMARY KEY,couple_id TEXT,title TEXT NOT NULL,description TEXT DEFAULT '',latitude REAL NOT NULL DEFAULT 0,longitude REAL NOT NULL DEFAULT 0,location_type TEXT NOT NULL DEFAULT 'date',photos TEXT NOT NULL DEFAULT '[]',memory_id TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS songs (id TEXT PRIMARY KEY,couple_id TEXT,title TEXT NOT NULL,artist TEXT NOT NULL DEFAULT '',url TEXT DEFAULT '',is_favorite INTEGER NOT NULL DEFAULT 0,is_background INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS gifts (id TEXT PRIMARY KEY,couple_id TEXT,title TEXT NOT NULL,description TEXT DEFAULT '',url TEXT DEFAULT '',image_url TEXT DEFAULT '',category TEXT DEFAULT 'wishlist',occasion TEXT DEFAULT '',price_range TEXT DEFAULT '',is_received INTEGER NOT NULL DEFAULT 0,for_partner TEXT DEFAULT 'partner2',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY,couple_id TEXT,content TEXT NOT NULL,message_type TEXT NOT NULL DEFAULT 'note',is_pinned INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY,couple_id TEXT,language TEXT NOT NULL DEFAULT 'en',theme TEXT NOT NULL DEFAULT 'dark',contact_links TEXT NOT NULL DEFAULT '[]',privacy_mode INTEGER NOT NULL DEFAULT 0,password_hash TEXT DEFAULT '',privacy_password TEXT DEFAULT '',notifications_enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_personalization (id TEXT PRIMARY KEY,couple_id TEXT,appearance TEXT NOT NULL DEFAULT '{}',background TEXT NOT NULL DEFAULT '{}',identity TEXT NOT NULL DEFAULT '{}',navigation TEXT NOT NULL DEFAULT '{}',active_workspace_id TEXT DEFAULT 'ws-main',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_workspaces (id TEXT PRIMARY KEY,couple_id TEXT,name TEXT NOT NULL,icon TEXT NOT NULL DEFAULT 'Heart',description TEXT DEFAULT '',is_default INTEGER NOT NULL DEFAULT 0,layout_mode TEXT NOT NULL DEFAULT 'bento',blocks TEXT NOT NULL DEFAULT '[]',theme_override TEXT,background_override TEXT,navigation_override TEXT,active_page_id TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_custom_pages (id TEXT PRIMARY KEY,couple_id TEXT,workspace_id TEXT,title TEXT NOT NULL,slug TEXT NOT NULL,icon TEXT NOT NULL DEFAULT 'FileText',description TEXT DEFAULT '',blocks TEXT NOT NULL DEFAULT '[]',is_default INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_assets (id TEXT PRIMARY KEY,couple_id TEXT,name TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'photo',url TEXT NOT NULL,thumbnail TEXT,size INTEGER DEFAULT 0,mime_type TEXT DEFAULT 'image/jpeg',tags TEXT NOT NULL DEFAULT '[]',is_favorite INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_saved_views (id TEXT PRIMARY KEY,couple_id TEXT,page_key TEXT NOT NULL,name TEXT NOT NULL,icon TEXT NOT NULL DEFAULT 'Bookmark',description TEXT DEFAULT '',filters TEXT NOT NULL DEFAULT '{}',sort_by TEXT,sort_order TEXT DEFAULT 'desc',display_mode TEXT DEFAULT 'grid',is_default INTEGER NOT NULL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_rules (id TEXT PRIMARY KEY,couple_id TEXT,name TEXT NOT NULL,trigger TEXT NOT NULL,condition TEXT NOT NULL DEFAULT '{}',action TEXT NOT NULL,action_payload TEXT NOT NULL DEFAULT '{}',is_enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_presets (id TEXT PRIMARY KEY,couple_id TEXT,name TEXT NOT NULL,description TEXT DEFAULT '',category TEXT DEFAULT 'Custom',author TEXT DEFAULT 'User',version TEXT DEFAULT '1.0.0',preview_thumbnail TEXT,tags TEXT NOT NULL DEFAULT '[]',appearance TEXT NOT NULL DEFAULT '{}',background TEXT NOT NULL DEFAULT '{}',navigation_style TEXT DEFAULT 'floating_dock',identity_decoration TEXT NOT NULL DEFAULT '{}',sample_blocks TEXT NOT NULL DEFAULT '[]',created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_config_revisions (id TEXT PRIMARY KEY,couple_id TEXT,timestamp TEXT DEFAULT CURRENT_TIMESTAMP,label TEXT NOT NULL DEFAULT 'Snapshot',snapshot TEXT NOT NULL DEFAULT '{}');

CREATE INDEX IF NOT EXISTS idx_timeline_couple_date ON timeline_events(couple_id,date);
CREATE INDEX IF NOT EXISTS idx_memories_couple_created ON memories(couple_id,created_at);
CREATE INDEX IF NOT EXISTS idx_journal_couple_date ON journal_entries(couple_id,date);
CREATE INDEX IF NOT EXISTS idx_mood_couple_created ON mood_entries(couple_id,created_at);
CREATE INDEX IF NOT EXISTS idx_bucket_couple_created ON bucket_list_items(couple_id,created_at);
CREATE INDEX IF NOT EXISTS idx_anniv_couple_date ON anniversaries(couple_id,date);
CREATE INDEX IF NOT EXISTS idx_map_couple_created ON map_locations(couple_id,created_at);
CREATE INDEX IF NOT EXISTS idx_songs_couple_created ON songs(couple_id,created_at);
CREATE INDEX IF NOT EXISTS idx_gifts_couple_created ON gifts(couple_id,created_at);
CREATE INDEX IF NOT EXISTS idx_messages_couple_created ON messages(couple_id,created_at);